/* Obsidian Prism (Unofficial T3 Code Port of RMvdesi/obsidian-prism, GPL-3.0) */
.dark [data-slot="sidebar"],
.dark [data-slot="sidebar-inner"] {
  background-color: #09090B !important;
  border-color: rgba(218, 228, 255, 0.052) !important;
}

.dark [data-thread-item],
:root:not(.dark) [data-thread-item] {
  border-radius: 7px !important;
  transition: background-color 130ms ease, border-color 130ms ease, color 130ms ease !important;
}

.dark [data-thread-item]:hover {
  background-color: rgba(255, 255, 255, 0.055) !important;
}

.dark [data-thread-item][aria-current="page"],
.dark [data-thread-item][data-active="true"],
.dark [data-thread-item][data-selected="true"] {
  background-color: rgba(255, 255, 255, 0.074) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), inset 2px 0 0 #5CC6FC !important;
}

:root:not(.dark) [data-thread-item][aria-current="page"],
:root:not(.dark) [data-thread-item][data-active="true"],
:root:not(.dark) [data-thread-item][data-selected="true"] {
  background-color: #FFFFFF !important;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.06), inset 2px 0 0 #2563EB !important;
}

.dark [data-chat-header] {
  background-color: rgba(11, 11, 14, 0.92) !important;
  border-bottom: 1px solid rgba(218, 228, 255, 0.052) !important;
}

.dark [data-workspace-area="conversation"] {
  background-color: #0E0E11 !important;
  background-image: radial-gradient(88% 42% at 50% 100%, rgba(66, 133, 244, 0.14) 0%, rgba(155, 114, 203, 0.06) 44%, transparent 78%), radial-gradient(70% 28% at 50% 0%, rgba(66, 133, 244, 0.045) 0%, transparent 72%) !important;
}

:root:not(.dark) [data-workspace-area="conversation"] {
  background-color: #F4F7FB !important;
  background-image: radial-gradient(85% 40% at 50% 100%, rgba(37, 99, 235, 0.08) 0%, rgba(124, 58, 237, 0.03) 45%, transparent 78%) !important;
}

.dark [data-user-message-bubble] {
  border-radius: 16px !important;
  background-color: #131418 !important;
  background-image: linear-gradient(rgba(255, 255, 255, 0.024) 0%, transparent 55%) !important;
  border: 1px solid rgba(255, 255, 255, 0.058) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.062), 0 6px 20px -10px rgba(0, 0, 0, 0.48) !important;
}

:root:not(.dark) [data-user-message-bubble] {
  border-radius: 16px !important;
  background-color: #EAF1FB !important;
  border: 1px solid rgba(15, 23, 42, 0.08) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 4px 14px -8px rgba(15, 23, 42, 0.14) !important;
}

.dark .chat-markdown blockquote {
  border-left: 2px solid rgba(102, 157, 246, 0.45) !important;
  background: linear-gradient(90deg, rgba(102, 157, 246, 0.07) 0%, transparent 72%) !important;
  border-radius: 2px 6px 6px 2px !important;
}

.dark .chat-markdown-codeblock {
  border-radius: 8px !important;
  background-color: #0D0F14 !important;
  border: 1px solid rgba(218, 228, 255, 0.078) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.065), 0 8px 24px -10px rgba(0, 0, 0, 0.45) !important;
}

[data-chat-composer-form] {
  overflow: visible !important;
}

.dark [data-slot="composer-host"] {
  position: relative !important;
  overflow: visible !important;
  border-radius: 14px !important;
  background-color: rgba(20, 21, 26, 0.92) !important;
  background-image: linear-gradient(172deg, rgba(255, 255, 255, 0.048) 0%, rgba(160, 185, 245, 0.016) 36%, rgba(10, 11, 16, 0.22) 100%) !important;
  border: 1px solid rgba(218, 228, 255, 0.095) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.10), 0 1px 2px rgba(0, 0, 0, 0.44), 0 8px 20px -6px rgba(0, 0, 0, 0.48), 0 20px 44px -14px rgba(0, 0, 0, 0.62) !important;
  transition: border-color 180ms ease, box-shadow 180ms ease !important;
}

.dark [data-slot="composer-host"]:focus-within {
  border-color: rgba(102, 157, 246, 0.44) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15), 0 0 0 1px rgba(102, 157, 246, 0.20), 0 8px 24px -6px rgba(0, 0, 0, 0.56) !important;
}

:root:not(.dark) [data-slot="composer-host"] {
  position: relative !important;
  overflow: visible !important;
  border-radius: 14px !important;
  background-color: rgba(255, 255, 255, 0.96) !important;
  background-image: linear-gradient(176deg, rgba(255, 255, 255, 0.98) 0%, rgba(241, 246, 255, 0.55) 100%) !important;
  border: 1px solid rgba(15, 23, 42, 0.11) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.96), 0 1px 3px rgba(15, 23, 42, 0.06), 0 10px 28px -6px rgba(30, 58, 138, 0.10) !important;
}

@keyframes op-clawd-idle {
  0%, 42%, 60%, 100% { transform: translateY(0px) scaleY(1); }
  48% { transform: translateY(-4px) scaleY(1.04); }
  54% { transform: translateY(0px) scaleY(0.96); }
}

@keyframes op-cat-idle {
  0%, 22%, 40%, 100% { transform: translateY(0px) scaleY(1); }
  28% { transform: translateY(-5px) scaleY(1.05); }
  34% { transform: translateY(0px) scaleY(0.95); }
}

[data-slot="composer-host"]::before {
  content: "" !important;
  position: absolute !important;
  right: 64px !important;
  bottom: calc(100% - 1px) !important;
  width: 40px !important;
  height: 25px !important;
  pointer-events: none !important;
  z-index: 20 !important;
  image-rendering: pixelated !important;
  background-repeat: no-repeat !important;
  background-size: contain !important;
  background-position: bottom center !important;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2016%2010%22%20shape-rendering%3D%22crispEdges%22%3E%3Cpath%20fill%3D%22%23d97757%22%20d%3D%22M2%200h12v1h-12zM2%201h12v1h-12zM2%202h2v1h-2zM5%202h6v1h-6zM12%202h2v1h-2zM2%203h2v1h-2zM5%203h6v1h-6zM12%203h2v1h-2zM2%204h12v1h-12zM0%205h16v1h-16zM0%206h16v1h-16zM2%207h12v1h-12zM3%208h1v1h-1zM5%208h1v1h-1zM10%208h1v1h-1zM12%208h1v1h-1zM3%209h1v1h-1zM5%209h1v1h-1zM10%209h1v1h-1zM12%209h1v1h-1z%22%2F%3E%3Cpath%20fill%3D%22%23141413%22%20d%3D%22M4%202h1v1h-1zM11%202h1v1h-1zM4%203h1v1h-1zM11%203h1v1h-1z%22%2F%3E%3C%2Fsvg%3E") !important;
  filter: drop-shadow(0 3px 6px rgba(217, 119, 87, 0.25)) !important;
  transform-origin: bottom center !important;
  animation: op-clawd-idle 4.8s ease-in-out infinite !important;
}

[data-slot="composer-host"]::after {
  content: "" !important;
  position: absolute !important;
  right: 18px !important;
  bottom: calc(100% - 1px) !important;
  width: 35px !important;
  height: 28px !important;
  pointer-events: none !important;
  z-index: 20 !important;
  image-rendering: pixelated !important;
  background-repeat: no-repeat !important;
  background-size: contain !important;
  background-position: bottom center !important;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2014%2011%22%20shape-rendering%3D%22crispEdges%22%3E%3Cpath%20fill%3D%22%23947fd6%22%20d%3D%22M0%200h1v1h-1zM11%200h1v1h-1zM0%201h2v1h-2zM10%201h2v1h-2zM0%202h12v1h-12zM0%203h12v1h-12zM0%204h2v1h-2zM3%204h6v1h-6zM10%204h2v1h-2zM0%205h2v1h-2zM3%205h6v1h-6zM10%205h2v1h-2zM13%205h1v1h-1zM0%206h12v1h-12zM13%206h1v1h-1zM0%207h14v1h-14zM0%208h12v1h-12zM1%209h1v1h-1zM3%209h1v1h-1zM8%209h1v1h-1zM10%209h1v1h-1zM1%2010h1v1h-1zM3%2010h1v1h-1zM8%2010h1v1h-1zM10%2010h1v1h-1z%22%2F%3E%3Cpath%20fill%3D%22%23141413%22%20d%3D%22M2%204h1v1h-1zM9%204h1v1h-1zM2%205h1v1h-1zM9%205h1v1h-1z%22%2F%3E%3Cpath%20fill%3D%22%23735eb5%22%20d%3D%22M13%204h1v1h-1z%22%2F%3E%3C%2Fsvg%3E") !important;
  filter: drop-shadow(0 3px 6px rgba(148, 127, 214, 0.28)) !important;
  transform-origin: bottom center !important;
  animation: op-cat-idle 5.4s ease-in-out infinite !important;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="composer-host"]::before,
  [data-slot="composer-host"]::after {
    animation: none !important;
  }
}

.dark [data-slot="popover-popup"],
.dark [data-slot="menu-popup"] {
  background-color: rgba(17, 18, 24, 0.96) !important;
  background-image: linear-gradient(rgba(182, 206, 255, 0.046) 0%, rgba(255, 255, 255, 0.012) 22%, transparent 52%) !important;
  border: 1px solid rgba(220, 230, 255, 0.105) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.095), 0 16px 40px -12px rgba(0, 0, 0, 0.58), 0 2px 8px -2px rgba(0, 0, 0, 0.38) !important;
}

.dark [data-slot="scroll-area-thumb"] {
  background-color: rgba(242, 242, 245, 0.16) !important;
  border-radius: 999px !important;
}

.dark [data-slot="scroll-area-thumb"]:hover {
  background-color: rgba(242, 242, 245, 0.30) !important;
}

.dark ::-webkit-scrollbar { width: 6px; height: 6px; }
.dark ::-webkit-scrollbar-track { background: transparent; }
.dark ::-webkit-scrollbar-thumb { background: rgba(242, 242, 245, 0.16); border-radius: 999px; }
.dark ::-webkit-scrollbar-thumb:hover { background: rgba(242, 242, 245, 0.30); }
